import {demand,accepted,shortfall,purchasing,recordProblems,operationalKey} from './operations.js';
import {readinessIssues,overdueDays,localDateKey} from './manufacturing.js';
export const opsEscape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(k,label,v,type='text')=>`<label>${label}<input name="${k}" type="${type}" value="${opsEscape(v)}" ${type==='number'?'min="0" step="1"':''} maxlength="2000"></label>`;
export function operationalFields(p,lead=false,fullEditor=false){return `<p class="quantity-explainer">${p.completedQty||0} parts made · ${Math.max(0,p.quantity-(p.completedQty||0))} required parts remaining · ${Math.max(0,demand(p)-(p.completedQty||0))} left to fabricate. Rework pieces are excluded from good pieces; scrap is discarded.</p>`+field('reworkQty','Current rework pieces (exclude from good count)',p.reworkQty||0,'number')+field('scrapQty','Scrapped pieces',p.scrapQty||0,'number')+(fullEditor?field('blockReason','Blocker reason',p.blockReason):'')+field('blockOwner','Blocker resolution owner',p.blockOwner)+field('blockNext','Blocker next action',p.blockNext)+field('blockExpected','Expected resolution',p.blockExpected,'date')+field('dependency','Dependency record ID / purchasing reference',p.dependency)+(lead?`<details class="advanced-fields full"><summary>Advanced production details</summary><div class="form-grid">${field('spareTarget','Optional spare target',p.spareTarget||0,'number')}${field('revision','Drawing / revision reference',p.revision)}${field('instructions','Setup / manufacturing instructions',p.instructions)}${field('location','Component storage location',p.location)}${field('shortCloseReason','Short-close reason (admin only, at least 5 characters)',p.shortCloseReason)}<label><input name="localOverride" type="checkbox" ${p.localOverride?'checked':''}> Keep local CAD metadata on BOM import</label></div><p>Production beyond required quantity is limited to the explicit spare target. Changing BOM-controlled fields without an override will be replaced at import.</p></details>`:'')+`<details class="part-history"><summary>Manufacturing details and history</summary><p>Internal ID: ${opsEscape(p.id)} · Revision: ${opsEscape(p.revision||'Not recorded')}</p><p>CAD/BOM identity: ${opsEscape(p.onshape?.key||'Manual record')}</p><p>Instructions: ${opsEscape(p.instructions||'Use reviewed drawing / dimensions')}</p><p>Location: ${opsEscape(p.location||'Not recorded')}</p><p>Blocked since: ${opsEscape(p.blockDate||'Not blocked')}</p><ul>${(p.history||[]).slice(-12).reverse().map(h=>'<li>'+opsEscape(h.label)+' · '+opsEscape(h.worker)+' · '+opsEscape(h.at)+'</li>').join('')}</ul></details>`;}
export function readOperationalFields(form,p){const out={};for(const k of ['blockReason','reworkQty','scrapQty','spareTarget','revision','instructions','location','shortCloseReason','blockOwner','blockNext','blockExpected','dependency'])if(form.elements[k])out[k]=['reworkQty','scrapQty','spareTarget'].includes(k)?Number(form.elements[k].value):operationalKey(form.elements[k].value);if(form.elements.localOverride)out.localOverride=form.elements.localOverride.checked;const next={...p,...out};if(next.blocked&&(!next.blockReason?.trim()||!next.blockOwner?.trim()||!next.blockNext?.trim()))throw Error('Add blocker reason, resolution owner and next action.');if(next.blocked&&!p.blocked)out.blockDate=localDateKey();return out;}

export function operationalExport(w,kind){if(kind==='purchase'||kind==='receiving')return [['Part','SKU','Vendor','Required pieces','Stock available','Ordered pieces','Inbound pieces','Received pieces','Pieces to order','Packs to order','Pack size','Shortfall','Order reference','Expected','Location'],...w.cots.filter(i=>kind==='purchase'?purchasing(i).order>0:purchasing(i).inbound>0).map(i=>{const q=purchasing(i);return [i.name,i.number,i.vendor,i.needed,q.stock,i.ordered,q.inbound,i.received,q.order,q.packs,i.packSize,q.missing,i.reference,i.eta,i.location];})];return [['Part','Number','Subsystem','Required','Parts made','Fabricated good','Remaining robot demand','Spare target','Spare shortfall','Rework','Scrap','Stage','Student','Process','Due','Blocker','Resolver','Next action','Location','Revision','CAD'],...w.parts.filter(p=>kind!=='spares'||p.spareTarget>0||accepted(p)>p.quantity).map(p=>[p.name,p.number,p.subsystem,p.quantity,accepted(p),p.completedQty,shortfall(p),p.spareTarget,Math.max(0,(p.spareTarget||0)-Math.max(0,accepted(p)-p.quantity)),p.reworkQty,p.scrapQty,p.status,p.owner||p.assignedTo,p.process,p.due,p.blockReason,p.blockOwner,p.blockNext,p.location,p.revision,p.cad])];}
